import {linkReviewController} from './link-review-app.mjs';
import {warningReview,warningTaskContext} from './warning-core.mjs';
import {warningConnections,selectWarningConnections,warningLinkTaskContext,WARNING_LINK_FILTERS} from './warning-links.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function warningDesk({getWorkspace,applyWorkspace,today,uid,canChange,feedback}) {
  let window={from:'2026-10-01',to:today(),scope:'All'},leadFilter='All leads';
  const reviews=linkReviewController({getWorkspace,applyWorkspace,today,uid,canChange,refresh:()=>render(),feedback});
  const source=r=>`<article class="warning-source"><p class="small-label">${esc(r.recordKey)} / ${r.synthetic?'SYNTHETIC':'ANALYST-ENTERED / UNVERIFIED'}</p><h4>${esc(r.title)}</h4><p><strong>Known by ${r.recordedAt}</strong> · Published ${r.reportedAt}<br>${esc(r.publisher)} · Group ${esc(r.originGroup)} · ${esc(r.claimState)} / ${esc(r.relation)}</p><blockquote class="source-excerpt">${esc(r.text)}</blockquote><p>Quoted date mentions: ${r.dateMentions.dates.slice(0,6).map(s=>`“${esc(s.quote)}” [${s.start}, ${s.end})${s.year===null?' (year unspecified)':''}`).join('; ')||'None in supported formats.'}${r.dateMentions.dates.length>6?' (first six shown)':''}</p>${r.dateMentions.invalidDates.length?`<p>Invalid calendar mentions: ${r.dateMentions.invalidDates.slice(0,6).map(s=>`“${esc(s.quote)}” [${s.start}, ${s.end})`).join('; ')}</p>`:''}<p class="muted">Parser state: ${esc(r.dateMentions.dateState)}. These mentions are not confirmed event times.</p>${r.supersedesDocumentId?`<p>Correction of ${esc(r.supersedesDocumentId)} · ${esc(r.revisionNote)}</p>`:''}${r.locator?`<p>Locator: ${esc(r.locator)}</p>`:''}${r.accessNote?`<p>Source conditions: ${esc(r.accessNote)}</p>`:''}${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open source reference (unverified)</a>`:''}</article>`;
  function connections() {
    const report=warningConnections(getWorkspace(),window),pairs=selectWarningConnections(report,leadFilter);
    const quote=s=>s?`“${esc(s.quote)}” [${s.start}, ${s.end})${s.year===null?' (year unspecified)':''}`:'No unique supported date mention';
    document.getElementById('warning-links').innerHTML=`<section class="report-link-section"><h3>Related-report leads</h3><p>Automatic lexical comparison across retained reports. Inspect shared wording and source context before deciding whether any connection matters.</p><p class="notice">${report.comparedRecords} of ${report.eligibleRecords} eligible records compared · ${report.excludedRecords} excluded by the newest-200 limit · ${report.qualifyingPairs} qualifying pairs · ${report.pairs.length} retained. TF-IDF cosine ≥ ${report.minSimilarity.toFixed(2)} and at least three shared tokens. Scores measure shared language, not threat likelihood.</p><label for="warning-link-filter">Inspect connection type</label><select id="warning-link-filter">${WARNING_LINK_FILTERS.map(f=>`<option${f===leadFilter?' selected':''}>${esc(f)}</option>`).join('')}</select><p>${pairs.length} of ${report.pairs.length} retained leads match this view. Showing ${Math.min(10,pairs.length)}. Filter counts apply only to the highest 40 retained pairs.</p>${pairs.slice(0,10).map(p=>`<article class="signal-card"><div class="case-heading"><h4>${esc(p.left.title)} / ${esc(p.right.title)}</h4><span class="chip">Cosine ${p.similarity.toFixed(3)}</span></div><p>Shared weighted terms: ${p.sharedTerms.map(esc).join(', ')}.</p><div class="warning-reason"><p>${p.sameRecordedGroup?'Same source-group label: check dependence; repetition is not independent corroboration.':'Different source-group labels: independence remains unverified.'}</p>${p.crossCase?'<p>Across existing cases: shared wording establishes no common actor or cause.</p>':''}${p.opposingStances?'<p>Opposing analyst-assigned stances: one Supports and one Challenges. This is not automatic contradiction recognition.</p>':''}<p>Date mention comparison: <strong>${esc(p.dateContext.relation)}</strong>. ${esc(p.dateContext.reason)}</p><p>Left: ${quote(p.dateContext.left)}<br>Right: ${quote(p.dateContext.right)}</p></div><details><summary>Inspect both original reports</summary><div class="report-pair">${source(p.left)}${source(p.right)}</div></details><button data-link-review-left="${esc(p.left.recordKey)}" data-link-review-right="${esc(p.right.recordKey)}">Review event context</button><button data-warning-link="${esc(p.left.recordKey)}" data-warning-link-right="${esc(p.right.recordKey)}">Prepare connection verification task</button></article>`).join('')||'<p class="empty">No retained leads in this view. Missing pairs do not establish unrelatedness or absence of a threat.</p>'}<details><summary>Connection method and limits</summary>${report.limitations.map(t=>`<p>${esc(t)}</p>`).join('')}<p>Date checks use limited English/Hindi named dates and ISO dates. A correction may mention an earlier event. Date compatibility does not establish event identity; mismatches remain visible and do not change cosine ordering. Real-place resolution and semantic event linking are not performed.</p></details></section>`;
  }
  function results() {
    const report=warningReview(getWorkspace(),window);
    document.getElementById('warning-results').innerHTML=`<div class="notice"><strong>${report.reviewCaseCount} case(s) with review gaps · ${report.recordsScanned} current records</strong><p>Applied window: ${report.window.from} to ${report.window.to} / ${esc(report.window.scope)}. All retained text is considered without keywords. Cases stay in workspace order, with no inferred severity ranking.</p></div><div id="warning-links"></div>${reviews.ledger(window.to)}<h3>Case context gaps</h3>${report.cases.map(c=>`<article class="signal-card"><div class="case-heading"><div><p class="small-label">${esc(c.scope)} / ${esc(c.area)}</p><h3>${esc(c.title)}</h3></div><span class="chip">${c.rules.length} review reasons</span></div><p>${c.recordCount} retained records · ${c.groups.length} recorded source groups. Existing case assignment; event identity remains unverified.</p>${c.rules.map(r=>`<div class="warning-reason"><h4>${esc(r.label)} · ${r.count}</h4><p>${esc(r.reason)}</p><details><summary>Inspect triggering source references</summary><p>${r.recordKeys.slice(0,30).map(esc).join(', ')}${r.recordKeys.length>30?` · first 30 of ${r.recordKeys.length} shown`:''}</p></details></div>`).join('')||'<p>No implemented context rules triggered. This does not establish safety or absence of a threat.</p>'}<div class="actions"><button data-task-case="${esc(c.assessmentId)}">View assessment</button>${c.rules.length?`<button data-warning-followup="${esc(c.assessmentId)}">Prepare context verification task</button>`:''}<button data-open-view="intake">Review staged sources</button></div><details><summary>Inspect as-of source timeline (${c.timeline.length} of ${c.recordCount})</summary><p class="muted">Ordered by recorded date, then publication date. ${c.hiddenTimelineCount?`${c.hiddenTimelineCount} older records omitted from this display; rule counts include them.`:'All eligible current records are shown.'} Superseded sources are replaced only once their correction is known.</p>${c.timeline.map(source).join('')}</details></article>`).join('')||'<p class="empty">No retained records in this window. Missing coverage is not evidence of safety. Add permitted sources through collection or document intake.</p>'}<details><summary>Review method and limits</summary>${report.limitations.map(l=>`<p>${esc(l)}</p>`).join('')}</details>`;
    connections();
  }
  function render() {
    document.getElementById('content').innerHTML=`<section class="panel"><div class="panel-heading"><div><h2>Early-warning review</h2><span class="muted">Source context → verification → reviewed evidence</span></div><button id="signal-scenario">Load fictional regional exercise</button></div><div class="case-body"><p>Review new source material and unresolved context before forming a warning. This desk automatically compares shared wording across retained reports and surfaces intake gaps, challenging evidence, repeated source groups and uncertain date mentions.</p><p class="notice">Rules identify verification work, not a predicted attack. No new source collection, semantic event resolution or background monitoring occurs here.</p><div class="actions"><button data-open-view="collection">Collect permitted sources</button><button data-open-view="signals">Compare reports and indicator mentions</button><button data-open-view="tasks">Open verification tasks</button></div><form id="warning-form"><div class="signal-fields"><div><label for="warning-from">Reports since</label><input id="warning-from" type="date" value="${window.from}" required></div><div><label for="warning-to">Known by</label><input id="warning-to" type="date" value="${window.to}" required></div><div><label for="warning-scope">Geographic scope</label><select id="warning-scope">${['All','Domestic','Cross-border','International'].map(s=>`<option${s===window.scope?' selected':''}>${s}</option>`).join('')}</select></div></div><p class="muted">Both publication and recorded dates must be no later than Known by. Publication must be within the selected window. Applying a window changes this view only.</p><p id="warning-error" class="error" role="alert"></p><button type="submit" class="primary">Refresh source review</button></form><div id="warning-results"></div></div></section>`;
    results();
  }
  document.addEventListener('submit',event=>{if(event.target.id!=='warning-form')return;event.preventDefault();try{const next={from:document.getElementById('warning-from').value,to:document.getElementById('warning-to').value,scope:document.getElementById('warning-scope').value};warningReview(getWorkspace(),next);window=next;results();document.getElementById('warning-error').textContent='';feedback('Source-context review refreshed. Evidence, judgments and tasks remain unchanged.');}catch(e){document.getElementById('warning-error').textContent=e.message;}});
  document.addEventListener('change',event=>{if(event.target.id!=='warning-link-filter')return;leadFilter=event.target.value;connections();feedback('Connection view changed. All retained leads remain available in All leads.');});
  document.addEventListener('click',event=>{const b=event.target.closest('button[data-link-review-left]');if(!b)return;try{reviews.open(b.dataset.linkReviewLeft,b.dataset.linkReviewRight,window.to);}catch(error){feedback(error.message,true);}});
  return {render,hasDraft:reviews.hasDraft,reset:reviews.reset,taskContext:id=>warningTaskContext(getWorkspace(),window,id),linkTaskContext:(left,right)=>warningLinkTaskContext(getWorkspace(),window,left,right)};
}
